-- mod-lan: Uldaman for the adventure route. Every mob in Uldaman drops the Staff of Prehistoria (7733) for players
-- who don't have it, so the Keystone door to Ironaya's chamber opens without the quest chain that gives it.
-- The loot ids are those of the creatures spawned on map 70; the map condition keeps the drop inside
-- Uldaman for creatures that also stand elsewhere.

DELETE FROM `creature_loot_template` WHERE `Item` = 7733 AND `Entry` IN (2748, 4847, 4848, 4849, 4850, 4851, 4852, 4853, 4854, 4855, 4857, 4860, 4861, 4863, 6906, 6907, 6908, 6910, 7011, 7012, 7022, 7023, 7030, 7076, 7077, 7078, 7175, 7206, 7228, 7290, 7291, 7309, 7320, 7321, 7396, 7397, 7405, 10120);

DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 1 AND `SourceEntry` = 7733 AND `SourceGroup` IN (2748, 4847, 4848, 4849, 4850, 4851, 4852, 4853, 4854, 4855, 4857, 4860, 4861, 4863, 6906, 6907, 6908, 6910, 7011, 7012, 7022, 7023, 7030, 7076, 7077, 7078, 7175, 7206, 7228, 7290, 7291, 7309, 7320, 7321, 7396, 7397, 7405, 10120);
